<?php
declare(strict_types=1);

require_once __DIR__ . '/config/database.php';
require_once __DIR__ . '/includes/auth.php';
requireVisitor();

$q = trim((string) ($_GET['q'] ?? ''));
$statement = $pdo->prepare('SELECT a.arsip_id,a.no_registrasi,a.no_surat,a.perihal,a.tanggal_surat,a.status_arsip,u.nama_unit,j.nama_jenis,COALESCE(k.kode_klasifikasi, \'-\') AS kode_klasifikasi,COALESCE(k.nama_klasifikasi, \'-\') AS nama_klasifikasi FROM arsip a JOIN unit_kerja u ON u.unit_id=a.unit_id JOIN jenis_surat j ON j.jenis_surat_id=a.jenis_surat_id LEFT JOIN klasifikasi_arsip k ON k.klasifikasi_id=a.klasifikasi_id WHERE (a.no_registrasi LIKE :q1 OR a.no_surat LIKE :q2 OR a.perihal LIKE :q3) ORDER BY a.created_at DESC LIMIT 100');
$statement->execute(['q1' => "%$q%", 'q2' => "%$q%", 'q3' => "%$q%"]);
$items = $statement->fetchAll();
$visitorUsername = trim((string) ($_SESSION['username'] ?? '')) ?: 'Visitor';
$visitorRole = trim((string) ($_SESSION['role_name'] ?? '')) ?: 'Visitor';
$assetBase = rtrim(str_replace('\\', '/', dirname((string) ($_SERVER['SCRIPT_NAME'] ?? ''))), '/');
?>
